mapper.insert:
INSERT INTO reservations (
    member_id, store_id, table_id, reservation_time, guest_count,
    status, cancelled_reason
) VALUES (
    #{memberId}, #{storeId}, #{tableId}, #{reservationTime}, #{guestCount},
    #{status}, #{cancelledReason}
)

mapper.update:
UPDATE reservations
SET status = #{status}
WHERE reservation_id = #{reservationId}

mapper.select:
SELECT *
FROM store_tables st
WHERE st.store_id = #{storeId}
AND st.capacity >= #{guestCount}
AND st.table_id NOT IN (
    SELECT table_id
    FROM reservations
    WHERE store_id = #{storeId}
    AND reservation_time = #{reservationTime}
    AND status != 'CANCELLED'
)
LIMIT 1

mapper.update:
UPDATE reservations
SET
    status = #{status},
    cancelled_reason = #{cancelledReason}
WHERE
    reservation_id = #{reservationId}
